class _CalcError(Exception):
    pass


def _parse_int(s: str) -> int:
    if len(s) <= 4000:
        return int(s)
    res = 0
    for i in range(0, len(s), 4000):
        chunk = s[i : i + 4000]
        res = res * (10 ** len(chunk)) + int(chunk)
    return res


def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_ws() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_atom() -> int:
        nonlocal pos
        skip_ws()
        if expr[pos] == "(":
            pos += 1
            val = parse_add()
            skip_ws()
            pos += 1  # ')'
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        return _parse_int(expr[start:pos])

    def parse_unary() -> int:
        nonlocal pos
        chain: list[tuple[bool, int]] = []
        while True:
            neg = False
            while True:
                skip_ws()
                if pos < n and expr[pos] == "-":
                    neg = not neg
                    pos += 1
                else:
                    break
            val = parse_atom()
            chain.append((neg, val))
            skip_ws()
            if pos < n and expr[pos] == "^":
                pos += 1
            else:
                break

        neg, acc = chain[-1]
        if neg:
            acc = -acc
        for i in range(len(chain) - 2, -1, -1):
            if acc < 0:
                raise _CalcError
            neg, base = chain[i]
            if acc == 0 or base == 1:
                p = 1
            elif base == 0:
                p = 0
            elif base == -1:
                p = -1 if (acc & 1) else 1
            else:
                p = base**acc
            acc = -p if neg else p
        return acc

    def parse_mul() -> int:
        nonlocal pos
        acc = parse_unary()
        while True:
            skip_ws()
            if pos < n and expr[pos] in ("*", "/", "%"):
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    acc *= rhs
                else:
                    if rhs == 0:
                        raise _CalcError
                    if op == "/":
                        q = abs(acc) // abs(rhs)
                        acc = -q if (acc < 0) ^ (rhs < 0) else q
                    else:
                        r = abs(acc) % abs(rhs)
                        acc = -r if acc < 0 else r
            else:
                break
        return acc

    def parse_add() -> int:
        nonlocal pos
        acc = parse_mul()
        while True:
            skip_ws()
            if pos < n and expr[pos] in ("+", "-"):
                op = expr[pos]
                pos += 1
                rhs = parse_mul()
                if op == "+":
                    acc += rhs
                else:
                    acc -= rhs
            else:
                break
        return acc

    try:
        return parse_add()
    except _CalcError:
        return "error"
